// Original Canvas scenery and miniature ninja characters, separate from gameplay rules.
const TAU=Math.PI*2,walkStates=new WeakMap(),patrolStates=new WeakMap();
function oval(c,x,y,rx,ry,color){c.beginPath();c.ellipse(x,y,rx,ry,0,0,TAU);c.fillStyle=color;c.fill();}
export function drawMotionBackdrop(c,m,kind){const theme=m.level.theme,cave=/Cave|Tunnel/.test(theme),candy=/Candy/.test(theme),space=/Orbital|Citadel/.test(theme),g=c.createLinearGradient(0,0,0,640);g.addColorStop(0,kind==='ninja'?'#172632':candy?'#302939':'#1d3341');g.addColorStop(1,cave?'#3d3651':kind==='ninja'?'#374c4a':'#39565b');c.fillStyle=g;c.fillRect(0,0,1000,640);
 for(let layer=0;layer<3;layer++){c.beginPath();c.moveTo(0,640);for(let x=0;x<=1000;x+=40)c.lineTo(x,220+layer*95+Math.sin(x/(90+layer*30)+layer)*35);c.lineTo(1000,640);c.fillStyle=['#83989a12','#688c8e18','#20383e35'][layer];c.fill();}
 if(kind==='ninja'){oval(c,850,100,44,44,'#ddd3ad44');oval(c,862,92,39,39,'#273e45');for(const x of [45,90,920,965]){c.fillStyle='#6d97825c';c.fillRect(x,145,8,400);for(let y=160;y<540;y+=55){c.strokeStyle='#b6c9a75a';c.lineWidth=2;c.beginPath();c.moveTo(x-2,y);c.lineTo(x+10,y);c.stroke();c.beginPath();c.ellipse(x+18,y-14,20,5,-.6,0,TAU);c.fillStyle='#6f9b7470';c.fill();}}for(const x of [130,830]){c.fillStyle='#222f43';c.fillRect(x,195,55,155);c.beginPath();c.moveTo(x-15,195);c.lineTo(x+28,169);c.lineTo(x+70,195);c.closePath();c.fillStyle='#596772';c.fill();c.fillStyle='#d3b27665';c.fillRect(x+16,218,23,36);}}
 else if(cave){for(let i=0;i<10;i++){const x=i*110;c.beginPath();c.moveTo(x,0);c.lineTo(x+32,80+(i%3)*20);c.lineTo(x+62,0);c.fillStyle=i%2?'#9d91bc33':'#91b8bd26';c.fill();}}
 else{for(const x of [35,890]){c.strokeStyle='#8eb4b638';c.lineWidth=3;c.strokeRect(x,110,75,230);for(let i=0;i<5;i++){c.strokeStyle='#bcd5cd38';c.beginPath();c.moveTo(x+5,140+i*37);c.lineTo(x+24,140+i*37);c.stroke();}oval(c,x+38,310,28,9,candy?'#d7a7b04a':space?'#a2a4e15a':'#8ed7bd55');}for(let i=0;i<24;i++)oval(c,(i*137)%1000,70+(i*73)%470,1.3,1.3,'#d4e6cf38');}
}
export function motionPose(m){const n=m.ninja,old=walkStates.get(m)||{x:n.x,y:n.y,walk:0,angle:-Math.PI/2};const dx=n.x-old.x,dy=n.y-old.y,d=Math.hypot(dx,dy);const pose={x:n.x,y:n.y,walk:old.walk+(d<60?d:0),angle:d>.01&&d<60?Math.atan2(dy,dx):old.angle};walkStates.set(m,pose);return pose;}
export function drawMiniNinja(c,x,y,{color='#a294ec',walk=0,angle=0,guard=false,stunned=false,scale=1}={}){c.save();c.translate(x,y);c.scale(scale,scale);oval(c,0,13,17,6,'#091d3266');const gait=Math.sin(walk/7)*4;c.strokeStyle='#27384d';c.lineCap='round';c.lineWidth=6;for(const side of [-1,1]){c.beginPath();c.moveTo(side*5,6);c.lineTo(side*7+gait*side,16);c.stroke();}c.fillStyle=color;c.beginPath();c.moveTo(-10,-8);c.quadraticCurveTo(-18,5,-10,10);c.quadraticCurveTo(0,15,11,9);c.quadraticCurveTo(16,0,10,-8);c.closePath();c.fill();c.strokeStyle='#b8c6c777';c.lineWidth=1;c.stroke();oval(c,0,-12,13,13,guard?'#725b61':'#30445a');c.fillStyle=guard?'#d4ae82':color;c.beginPath();c.roundRect(-12,-19,24,9,4);c.fill();c.fillStyle='#dbddd5';c.fillRect(-8,-13,16,6);for(const side of [-1,1])oval(c,side*4+Math.cos(angle)*1.5,-10+Math.sin(angle),1.5,2,'#24384a');c.fillStyle=guard?'#a48578':color;c.beginPath();c.moveTo(-9,-5);c.lineTo(-20-gait,-1);c.lineTo(-13,3);c.lineTo(-5,0);c.fill();c.strokeStyle='#ccdad677';c.lineWidth=2;c.beginPath();c.moveTo(-8,2);c.lineTo(8,2);c.stroke();if(stunned){c.fillStyle='#e4ce91';for(const side of [-1,1]){c.beginPath();c.arc(side*13,-27,2.5,0,TAU);c.fill();}}c.restore();}
export function drawFan(c,x,y,time=0){c.save();c.translate(x,y);c.strokeStyle='#a5ced0';c.lineWidth=2;c.beginPath();c.arc(0,0,18,0,TAU);c.stroke();for(let i=0;i<3;i++){c.save();c.rotate(i*TAU/3+time/450);oval(c,0,-8,5,10,'#82b9bd');c.restore();}oval(c,0,0,4,4,'#d2e0d3');c.restore();}

export function patrolPose(m,g){let entries=patrolStates.get(m);if(!entries){entries=new Map();patrolStates.set(m,entries);}const old=entries.get(g.index)||{x:g.x,y:g.y,walk:0},d=Math.hypot(g.x-old.x,g.y-old.y),pose={x:g.x,y:g.y,walk:old.walk+(!g.stunned&&d<60?d:0)};entries.set(g.index,pose);return pose;}
